text:
{
  "title_novice": "Повторные замеры сопротивления во времени",
  "summary": [
    {"text": "Для большей части продуктивных коллекторов показания зондов со средним и большим радиусами исследования со временем снижаются.", "claims": ["c1"]},
    {"text": "Продуктивный коллектор выделяют по значительному росту удельного сопротивления ρφ на диаграмме, снятой после испытания.", "claims": ["c2", "c3"]},
    {"text": "Метод называют «исследование — испытание — исследование»: замер, испытание, повторный замер.", "claims": ["c3", "c4"]}
  ],
  "claims": [
    {"key": "c1", "text": "На повторных диаграммах у большей части продуктивных коллекторов показания зондов со средним и большим радиусами исследования со временем снижаются.", "kind": "observation", "unit_id": "u-022-cd10af", "page": 22, "quote": "Для большей части продуктивных коллекторов характерно снижение во времени показаний зондов со средним и большим радиусами исследования на диаграммах повторных измерений.", "numbers": [], "question": null},
    {"key": "c2", "text": "Продуктивный коллектор выделяют по значительному росту ρφ экранированного или индукционного зонда на диаграмме, снятой после испытания КИИ.", "kind": "inference", "unit_id": "u-022-cd10af", "page": 22, "quote": "экранированного или индукционного зондов на диаграмме, зарегистрированной после испытания в данном интервале испытателями на трубах (КИИ)", "numbers": [], "question": null},
    {"key": "c3", "text": "Способ называют методикой «исследование — испытание — исследование»; по нему продуктивный коллектор выделяется по росту показаний.", "kind": "observation", "unit_id": "u-022-cd10af", "page": 22, "quote": "По методике «исследование — испытание — исследование» продуктивный коллектор выделяется", "numbers": [], "question": null},
    {"key": "c4", "text": "Испытание проводят в данном интервале испытателем пластов на трубах, сокращённо КИИ.", "kind": "observation", "unit_id": "u-022-cd10af", "page": 22, "quote": "в данном интервале испытателями на трубах (КИИ)", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "На повторных диаграммах показания зондов со средним и большим радиусом у большей части продуктивных коллекторов снижаются со временем.", "claims": ["c1"], "hypothesis": false},
    {"text": "Зонд с большим радиусом исследования «видит» породу дальше от ствола скважины, чем зонд с малым радиусом.", "claims": [], "hypothesis": true},
    {"text": "Фильтрат бурового раствора уходит в пласт вокруг скважины, и эта зона со временем меняется; повторный замер фиксирует такое изменение.", "claims": [], "hypothesis": true},
    {"text": "Метод «исследование — испытание — исследование» ставит испытание испытателем на трубах (КИИ) между двумя замерами.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Если после испытания ρφ экранированного или индукционного зонда заметно вырос, интервал выделяют как продуктивный коллектор.", "claims": ["c2"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Сравнить два или больше повторных замеров по одному интервалу и смотреть, как меняются показания зондов со средним и большим радиусом.", "claims": ["c1"], "hypothesis": false},
    {"text": "Сравнить замер после испытания КИИ с замером до испытания. Значительный рост ρφ экранированного или индукционного зонда указывает на продуктивность.", "claims": ["c2", "c4"], "hypothesis": false},
    {"text": "Не делать вывод по одному замеру: снижение и рост показаний описаны в тексте как признаки, которые сравнивают между замерами.", "claims": ["c1", "c3"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Текст говорит о «большей части» коллекторов, а не обо всех. Исключения в узле не описаны.", "claims": ["c1"], "hypothesis": false},
    {"text": "Направления изменения разные: на повторных диаграммах показания снижаются, после испытания ρφ растёт. Текст не объясняет, почему.", "claims": ["c1", "c2"], "hypothesis": false},
    {"text": "В узле нет числового порога для «значительного» роста ρφ.", "claims": ["c2"], "hypothesis": false},
    {"text": "В первой фразе речь о зондах со средним и большим радиусами, во второй — об экранированном или индукционном зонде. Прямо о том, что эти зонды имеют средний и большой радиус, текст не пишет.", "claims": ["c1", "c2"], "hypothesis": false},
    {"text": "Испытание КИИ относится к данному интервалу, а не ко всей скважине.", "claims": ["c4"], "hypothesis": false},
    {"text": "Текст ссылается на рис. 6, но в этот узел он не входит.", "claims": ["c2"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Что делает испытание с пластом", "text": "Испытание отбирает флюид из интервала и меняет зону вокруг скважины. Это объяснение механизма не дано в узле, поэтому оно помечено как гипотеза.", "claims": [], "hypothesis": true}
  ],
  "procedure": [
    {"text": "Исследование: замер интервала до испытания.", "claims": ["c3"]},
    {"text": "Испытание интервала испытателем на трубах (КИИ).", "claims": ["c4", "c3"]},
    {"text": "Повторное исследование: замер после испытания.", "claims": ["c2"]},
    {"text": "Сравнить замеры. Значительное увеличение ρφ экранированного или индукционного зонда — признак продуктивного коллектора.", "claims": ["c2", "c3"]}
  ],
  "numbers_conditions": [
    {"text": "Снижение показаний во времени характерно для большей части продуктивных коллекторов; речь о зондах со средним и большим радиусами исследования.", "claims": ["c1"]},
    {"text": "Признак продуктивности: значительное увеличение ρφ экранированного или индукционного зонда после испытания КИИ в данном интервале.", "claims": ["c2"]},
    {"text": "Численного порога «значительного» увеличения в тексте нет.", "claims": ["c2"]}
  ],
  "terms_defined": [
    {"term": "повторные (временные) замеры", "term_en": "repeat (time-lapse) logging", "abbr": "", "definition": "Замеры одного и того же интервала скважины в разное время. По их сравнению видно, как показания меняются со временем.", "claims": ["c1"]},
    {"term": "расформирование зоны проникновения", "term_en": "breakdown of the invasion zone", "abbr": "", "definition": "Постепенное исчезновение отличия прискважинной зоны, куда вошёл фильтрат раствора, от неизменённой части пласта. В узле прямо не определено; смысл следует из повторных замеров и контекста главы.", "claims": []},
    {"term": "КИИ (испытатель на трубах)", "term_en": "formation tester on drill pipe", "abbr": "КИИ", "definition": "Испытатель пластов на трубах. Им испытывают интервал скважины, и затем сравнивают замеры до и после испытания.", "claims": ["c4"]},
    {"term": "радиус исследования", "term_en": "depth of investigation", "abbr": "", "definition": "Расстояние от ствола скважины, с которого зонд даёт основную часть своего показания. Общее определение, в узле не приведено дословно.", "claims": []}
  ],
  "terms_used": ["зонд", "экранированный зонд (БК)", "индукционный зонд (ИК)", "удельное сопротивление", "зона проникновения", "фильтрат бурового раствора", "продуктивный коллектор", "ствол скважины"],
  "formulas": [],
  "tables": [],
  "figures": [],
  "worked_examples": [],
  "book_problems": [],
  "misconception": {
    "pack_id": "M06",
    "wrong": "Высокое сопротивление на одном замере всегда означает нефть, поэтому повторные замеры и испытание не нужны.",
    "right": "Продуктивность выделяют по изменению показаний между замерами и по росту ρφ после испытания КИИ, а не по одному значению.",
    "claims": ["c1", "c2", "c3"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Повторные диаграммы зондов со средним и большим радиусом исследования по одному интервалу, снятые в разное время.", "claims": ["c1"], "hypothesis": false},
      {"text": "Диаграмма экранированного (БК) или индукционного (ИК) зонда, снятая после испытания КИИ в том же интервале.", "claims": ["c2", "c4"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Направление изменения показаний со временем: для большей части продуктивных коллекторов — снижение.", "claims": ["c1"], "hypothesis": false},
      {"text": "Признак продуктивного коллектора: значительный рост ρφ после испытания.", "claims": ["c2"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "«Большая часть» — не все коллекторы. Исключения в узле не описаны.", "claims": ["c1"], "hypothesis": false},
      {"text": "Порог «значительного» роста в тексте не задан.", "claims": ["c2"], "hypothesis": false},
      {"text": "Направления изменений при повторных замерах и после испытания в тексте разные; причина не объяснена.", "claims": ["c1", "c2"], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": "IT05",
    "analogy": "(гипотеза) Повторный замер похож на сравнение двух снимков кэша: ближние датчики видят кэш, дальние — исходные данные. Разница во времени показывает, что кэш сменился.",
    "breaks_where": "Кэш сам расформировывается, а глубина зоны зависит от раствора и пористости. Для пласта это физическое явление, а не программная очистка."
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": true,
    "why": "Продуктивность видна не в одном значении, а в изменении показаний во времени и после испытания. Без этого нельзя понять, зачем нужны повторные замеры."
  },
  "inefficiency": {
    "inputs": [
      "Повторные диаграммы зондов со средним и большим радиусом по одному интервалу",
      "Диаграмма экранированного или индукционного зонда после испытания КИИ в том же интервале"
    ],
    "manual_steps": [
      "Сопоставить исходный и повторный замер (гипотеза: визуально, в тексте не описано)",
      "Организовать испытание КИИ в интервале",
      "Сравнить замер после испытания с замером до него"
    ],
    "judgment_points": [
      "Какой рост ρφ считать значительным: в тексте нет порога",
      "Учесть, что снижение показаний характерно для большей части коллекторов, а не для всех"
    ],
    "time": [
      "Повторные замеры разнесены во времени; сколько времени между ними, в узле не сказано (гипотеза: зависит от условий скважины)",
      "Испытание КИИ требует отдельного спуска и времени на работу (гипотеза)"
    ],
    "typical_errors": [
      "Считать одно снижение показаний признаком нефти, хотя текст говорит о большей части коллекторов",
      "Сравнивать замеры до и после испытания без учёта того, что они сделаны в один и тот же интервал",
      "Считать высокое сопротивление признаком нефти без повторного замера и испытания (гипотеза: связано с M06)"
    ]
  },
  "videoability": {
    "time_change": true,
    "invisible_visible": true,
    "scale_jump": false,
    "counterintuitive": false,
    "cause_effect": false
  },
  "data_decision": true,
  "state_model": "(гипотеза модели) Прискважинная зона пласта со временем меняется; зонды средней и большой глубинности фиксируют эту смену, а испытание КИИ меняет условия перед вторым замером.",
  "links": [
    {"target": "n30", "type": "prerequisite", "note": "Глубина исследования и глубокое проникновение: зонды видят разную глубину пласта."},
    {"target": "n38", "type": "prerequisite", "note": "Сопоставление кривых сопротивления и расхождение кривых как признак нефти."},
    {"target": "n40", "type": "example", "note": "Повторные замеры нейтронными методами за колонной."},
    {"target": "n43", "type": "to_data", "note": "Когда и с каким интервалом делать повторные замеры."},
    {"target": "n53", "type": "example", "note": "Испытатели пластов КИИ и ОПТ как источник данных для второго шага метода."}
  ],
